            new Quote { Id = "https://en.wikiquote.org/wiki/Oscar_Wilde", Text = "And, after all, what is a fashion? From the artistic point of view, it is usually a form of ugliness so intolerable that we have to alter it every six months.", Author = "Oscar Wilde" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Oscar_Wilde", Text = "We have really everything in common with America nowadays, except, of course, language.", Author = "Oscar Wilde" },
